import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose1d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose1d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool has_bias
) {
    int total_elements = batch_size * out_channels * output_length;
    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    for (int idx = tid; idx < total_elements; idx += blockDim.x * gridDim.x) {
        int b = idx / (out_channels * output_length);
        int oc = (idx % (out_channels * output_length)) / output_length;
        int o_idx = idx % output_length;

        float sum = 0.0f;

        for (int ic = 0; ic < in_channels; ++ic) {
            for (int k = 0; k < kernel_size; ++k) {
                int input_pos = (o_idx - k * dilation + padding) / stride;
                int remainder = (o_idx - k * dilation + padding) % stride;

                if (input_pos >= 0 && input_pos < input_length && remainder == 0) {
                    int input_idx = b * in_channels * input_length + ic * input_length + input_pos;
                    int weight_idx = ic * out_channels * kernel_size + oc * kernel_size + k;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }

        if (has_bias) {
            sum += bias[oc];
        }

        output[idx] = sum;
    }
}

torch::Tensor conv_transpose1d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int output_length
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_length = input.size(2);
    int out_channels = weight.size(1);
    int kernel_size = weight.size(2);

    auto output = torch::zeros({batch_size, out_channels, output_length}, input.options());
    bool has_bias = bias.defined() && bias.size(0) > 0;

    int threads = 256;
    int blocks = (output.numel() + threads - 1) / threads;

    conv_transpose1d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding,
        dilation,
        has_bias
    );

    return output;
}
"""

conv_transpose1d_cpp = """
torch::Tensor conv_transpose1d_cuda_forward(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int stride, int padding, int dilation, int output_length);
"""

conv_transpose1d = load_inline(
    name='conv_transpose1d',
    cpp_sources=conv_transpose1d_cpp,
    cuda_sources=conv_transpose1d_source,
    functions=['conv_transpose1d_cuda_forward'],
    verbose=False,
    extra_cuda_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, 
                 stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        self.weight = nn.Parameter(torch.Tensor(in_channels, out_channels, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        n = self.in_channels * self.kernel_size
        stdv = 1.0 / math.sqrt(n)
        self.weight.data.uniform_(-stdv, stdv)
        if self.bias is not None:
            self.bias.data.uniform_(-stdv, stdv)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        output_length = (x.size(2)-1)*self.stride - 2*self.padding + self.dilation*(self.kernel_size-1) + 1
        bias_tensor = self.bias if self.bias is not None else torch.tensor([], device=x.device)
        return conv_transpose1d.conv_transpose1d_cuda_forward(
            x, self.weight, bias_tensor, self.stride, 
            self.padding, self.dilation, output_length
        )
